import Crypto
import Foundation

/// Shared browser markup for Swan's two OAuth browser surfaces: the localhost
/// development bridge and the public authorization server. Both render the same
/// login and consent pages so a change to either is a change to one file.
///
/// The stylesheet is a pinned daisyUI build (Tailwind CSS v4 + daisyUI 5),
/// generated by `Scripts/build-browser-css.sh` and inlined so the pages need no
/// network fetch and no static asset route. `browserStyleCSPSource` is derived
/// from the literal below at run time, so the CSP hash can never drift from the
/// bytes actually served.
enum SwanBrowserPages {
    static func login(csrf: String) -> String {
        page(
            title: "Sign in",
            body: """
            <h1 class="card-title text-xl">Sign in</h1>\
            <form method="post" action="/oauth/authorize" class="flex flex-col gap-4">\
            <input type="hidden" name="csrf" value="\(escape(csrf))">\
            <fieldset class="fieldset gap-1"><legend class="fieldset-legend">Handle</legend>\
            <input name="handle" class="input w-full" autocomplete="username" required autofocus></fieldset>\
            <fieldset class="fieldset gap-1"><legend class="fieldset-legend">Password</legend>\
            <input name="password" type="password" class="input w-full" autocomplete="current-password" required></fieldset>\
            <button type="submit" class="btn btn-primary w-full">Continue</button>\
            </form>
            """
        )
    }

    static func consent(
        csrf: String,
        subject: String,
        clientID: String,
        scopes: Set<String>
    ) -> String {
        let scopeItems = scopes.sorted().map {
            "<li><code class=\"badge badge-neutral badge-sm font-mono\">\(escape($0))</code></li>"
        }.joined()
        return page(
            title: "Authorize client",
            body: """
            <h1 class="card-title text-xl">Authorize client</h1>\
            <div class="text-sm"><span class="text-base-content/60">Account</span>\
            <div class="font-mono break-all">\(escape(subject))</div></div>\
            <div class="text-sm"><span class="text-base-content/60">Client</span>\
            <div class="font-mono break-all">\(escape(clientID))</div></div>\
            <div class="flex flex-col gap-2"><span class="text-sm text-base-content/60">Requested access</span>\
            <ul class="flex flex-wrap gap-2">\(scopeItems)</ul></div>\
            <form method="post" action="/oauth/authorize/consent" class="card-actions justify-end gap-2">\
            <input type="hidden" name="csrf" value="\(escape(csrf))">\
            <button name="decision" value="deny" type="submit" class="btn btn-outline">Deny</button>\
            <button name="decision" value="approve" type="submit" class="btn btn-primary">Approve</button>\
            </form>
            """
        )
    }

    /// The `style-src` source expression for the inlined stylesheet. Keeping the
    /// hash derived rather than written down means `default-src 'none'` stays
    /// intact: no `'unsafe-inline'`, no external style origin.
    static let browserStyleCSPSource: String = {
        let digest = SHA256.hash(data: Data(styleSheet.utf8))
        return "'sha256-\(Data(digest).base64EncodedString())'"
    }()

    static func escape(_ value: String) -> String {
        value.replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#39;")
    }

    private static func page(title: String, body: String) -> String {
        """
        <!doctype html><html lang="en"><head><meta charset="utf-8">\
        <meta name="viewport" content="width=device-width, initial-scale=1">\
        <meta name="color-scheme" content="light dark">\
        <title>\(escape(title)) - Swan</title><style>\(styleSheet)</style></head>\
        <body class="bg-base-200 text-base-content min-h-screen flex items-start justify-center p-6">\
        <main class="card bg-base-100 w-full max-w-md shadow-sm"><div class="card-body gap-5">\(body)</div></main>\
        </body></html>
        """
    }
}
